const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const show=v=>typeof v==='string'?v:JSON.stringify(v);
function network(v){
 const nodes=new Map(v.nodes.map(n=>[n.id,n])),active=v.active||[];
 return `<div class="network-wrap"><svg class="node-network" viewBox="0 0 600 ${v.height||240}" role="img" aria-label="${esc(v.note||'Node relationships')}">${v.edges.map(e=>{const a=nodes.get(e.from),b=nodes.get(e.to);if(!a||!b)return '';return `<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="#a9b49c" stroke-width="2"/>${e.label?`<text class="edge-label" x="${(a.x+b.x)/2+7}" y="${(a.y+b.y)/2}">${esc(e.label)}</text>`:''}`;}).join('')}${v.nodes.map(n=>`<g><circle cx="${n.x}" cy="${n.y}" r="${String(n.label).length>5?31:23}" fill="${active.includes(n.id)?'#f1c4a6':'#dce8d0'}" stroke="${active.includes(n.id)?'#b76539':'#91a47e'}"/><text x="${n.x}" y="${n.y+5}" text-anchor="middle">${esc(n.label)}</text></g>`).join('')}</svg></div>${v.note?`<p class="viz-caption">${esc(v.note)}</p>`:''}`;
}
export function expansionArt(g){return `<div class="strategy-mini" aria-hidden="true">${({Array:'[ i → j ]',Binary:'010 ⊕ 101','Dynamic Programming':'dp[i] ← ?',Graph:'● — ● — ●',Interval:'[1,3] → [3,5]',Matrix:'↻ [ r, c ]',String:'a b ↔ b a',Heap:'△ ↔ △',Tree:'⑂ → ⑂','Linked List':'● → ● → ∅'})[g.category]}</div>`;}
function visual(v){
 let html='';const active=v.active||[],marked=v.marked||[];
 if(v.network)html+=network(v.network);
 if(v.chains)html+=`<div class="node-chains">${v.chains.map(chain=>`<div class="node-chain"><small>${esc(chain.label)}</small><div class="node-chain-row">${chain.nodes.map(node=>`<span class="linked-node ${(v.activeNodes||[]).includes(node.id)?'active':''}"><small>${esc(node.id)}</small><b>${esc(node.value)}</b></span><span class="link-arrow" aria-hidden="true">→</span>`).join('')}<span class="null-node">${v.cycleTo>=0?'↩ @'+v.cycleTo:'null'}</span></div></div>`).join('')}</div><p class="viz-caption">Node IDs identify references; equal values can belong to different nodes.</p>`;
 if(v.heaps)html+=`<div class="heap-pair">${v.heaps.map(heap=>{const nodes=heap.values.map((value,i)=>{const level=Math.floor(Math.log2(i+1)),first=2**level-1;return {id:i,label:value,x:600*(i-first+1)/(2**level+1),y:35+level*65};});return `<section><h3>${esc(heap.label)}</h3>${network({nodes,edges:nodes.slice(1).map(n=>({from:Math.floor((n.id-1)/2),to:n.id})),active:nodes.length?[0]:[],height:Math.max(100,...nodes.map(n=>n.y+35)),note:nodes.length?'Root highlighted':'Empty heap'})}</section>`;}).join('')}</div>`;
 if(v.bits)html+=`<div class="trace-bits">${v.bits.map(([label,n])=>`<div><strong>${esc(label)}</strong><code>${(n>>>0).toString(2).padStart(32,'0').match(/.{4}/g).join(' ')}</code></div>`).join('')}</div>`;
 if(v.array)html+=`<div class="trace-array">${v.array.map((n,i)=>`<div class="trace-cell ${active.includes(i)?'active':''}"><small>${i}</small><strong>${esc(show(n)===' '?'␠':show(n))}</strong></div>`).join('')}</div>`;
 if(v.matrix){const cols=v.matrix[0]?.length||1;html+=`<div class="trace-matrix-wrap"><div class="trace-matrix" style="--cols:${cols+1}"><div></div>${v.matrix[0].map((_,x)=>`<div class="trace-axis">${esc(v.colLabels?.[x]??x)}</div>`).join('')}${v.matrix.map((row,y)=>`<div class="trace-axis">${esc(v.rowLabels?.[y]??y)}</div>${row.map((n,x)=>`<div class="trace-cell ${active.includes(y*cols+x)?'active':''} ${marked.includes(y*cols+x)?'marked':''}"><strong>${esc(n)}</strong></div>`).join('')}`).join('')}</div></div><p class="viz-caption">Rows and columns use zero-based indices. Orange marks the current decision; green marks discovered cells.</p>`;}
 if(v.graph){const {n,edges,processed,roots}=v.graph,pos=Array.from({length:n},(_,i)=>({x:220+140*Math.cos(i*2*Math.PI/n-Math.PI/2),y:140+100*Math.sin(i*2*Math.PI/n-Math.PI/2)}));html+=`<svg class="trace-graph" viewBox="0 0 440 280" role="img" aria-label="Undirected graph with ${n} nodes. Edges: ${esc(edges.map(e=>e.join(' to ')).join(', '))}">${edges.map(([a,b],i)=>`<line x1="${pos[a].x}" y1="${pos[a].y}" x2="${pos[b].x}" y2="${pos[b].y}" stroke="${i===processed?'#e78958':i<processed?'#8aab78':'#d5d8cb'}" stroke-width="${i===processed?5:2}"/>`).join('')}${pos.map((p,i)=>`<circle cx="${p.x}" cy="${p.y}" r="24" fill="${['#cce1bd','#dcd0ec','#f1d1ba','#b9dbe1','#ece0ac'][roots[i]%5]}"/><text x="${p.x}" y="${p.y+5}" text-anchor="middle">${i}</text>`).join('')}</svg><p class="viz-caption">Orange: current edge. Node colors show the current disjoint sets.</p>`;}
 if(v.intervals){const all=v.intervals.flat(),min=Math.min(...all,0),max=Math.max(...all,1),x=n=>50+380*(n-min)/Math.max(1,max-min);html+=`<svg class="interval-viz" viewBox="0 0 480 ${Math.max(70,v.intervals.length*55+20)}" role="img" aria-label="Intervals ${esc(JSON.stringify(v.intervals))}">${v.intervals.map(([a,b],i)=>`<text x="5" y="${30+i*55}">${i}</text><line x1="${x(a)}" x2="${x(b)}" y1="${25+i*55}" y2="${25+i*55}" stroke="${active.includes(i)?'#e78958':'#a997c4'}" stroke-width="9" stroke-linecap="round"/><text x="${x(a)}" y="${47+i*55}" text-anchor="middle">${a}</text><text x="${x(b)}" y="${47+i*55}" text-anchor="middle">${b}</text>`).join('')}</svg>`;}
 if(v.buckets)html+=`<div class="trace-buckets">${v.buckets.map(([value,count])=>`<div><strong>${value}</strong><span style="--amount:${count}"></span><small>${count} occurrences</small></div>`).join('')}</div>`;
 if(v.saved)html+=`<div class="queue-box"><strong>SAVED STATE</strong><div class="trace-saved">${esc(JSON.stringify(v.saved))}</div></div>`;
 if(v.records)html+=`<div class="record-row trace-records">${Object.entries(v.records).map(([key,value])=>`<div>${esc(key)}<strong>${esc(show(value))}</strong></div>`).join('')}</div>`;
 if(Object.hasOwn(v,'result'))html+=`<div class="trace-result"><small>RESULT</small><strong>${esc(JSON.stringify(v.result))}</strong></div>`;
 return html;
}
export function expansionBoard(g,s){
 const step=s.trace.steps[Math.min(s.index,s.trace.steps.length-1)];
 return `<div class="game-layout"><section class="game-board advanced-board"><div class="board-top"><span>ROUND ${s.round+1} OF ${g.rounds.length}</span><span class="target">${g.tag}</span></div><div class="trace-progress"><span>Decision ${Math.min(s.index+1,s.trace.steps.length)} of ${s.trace.steps.length}</span><progress max="${s.trace.steps.length}" value="${s.index}"></progress></div><h2 class="instruction">${esc(step.title)}</h2><p class="subtext">${esc(step.detail)}</p>${visual(step.view)}<div class="controls trace-choices">${s.done?'':step.choices.map((label,i)=>`<button class="btn" data-action="decide" data-value="${i}">${esc(label)}</button>`).join('')}</div><div id="game-feedback" aria-live="polite">${s.message?`<p class="feedback ${s.error?'error':''}">${esc(s.message)}${s.done?`<br><strong>${s.round+1===g.rounds.length?'Pattern unlocked. Opening your coding exercise…':'Loading the next round…'}</strong>`:''}</p>`:''}</div></section><aside class="explanation"><div class="icon">✳</div><h2>${g.concept}</h2><p>${esc(g.lesson)}</p><div class="divider">Read the highlighted state.<br>Choose the next algorithm move.</div></aside></div>`;
}
